using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.VisualBasic;

namespace WebForms.Formatting;

/// <summary>
/// Generated files are left alone: reformatting them fights the generator (designer files are byte-for-byte
/// Visual Studio output, see <c>webforms designer --style auto</c>) and is lost on the next regeneration.
/// </summary>
internal static class GeneratedCode
{
    public static string? Reason(string? fileName, SyntaxNode root)
    {
        if (fileName is not null)
        {
            var name = Path.GetFileName(fileName);
            if (name.EndsWith(".designer.vb", StringComparison.OrdinalIgnoreCase))
            {
                return "designer file";
            }

            if (name.EndsWith(".g.vb", StringComparison.OrdinalIgnoreCase) || name.EndsWith(".g.i.vb", StringComparison.OrdinalIgnoreCase))
            {
                return "generated file";
            }
        }

        // The "<auto-generated>" header comment that Visual Studio, wsdl.exe, resgen etc. write.
        foreach (var trivia in root.GetLeadingTrivia())
        {
            if (trivia.IsKind(SyntaxKind.CommentTrivia) &&
                (trivia.ToString().Contains("<auto-generated", StringComparison.OrdinalIgnoreCase) ||
                 trivia.ToString().Contains("<autogenerated", StringComparison.OrdinalIgnoreCase)))
            {
                return "<auto-generated> file";
            }
        }

        return null;
    }
}
